/*
 * A335237  Numbers whose binary indices are not a singleton nor pairwise
 *          coprime.
 * https://oeis.org/A335237
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   sequence of numbers whose binary indices are not a singleton nor
 *            pairwise coprime; * generated by scanning integers and testing
 *            the condition
 * Range:     u8 n <= 62, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Euclidean algorithm for idx_t. */
static idx_t gcd_idx(idx_t a, idx_t b) {
    while (b) {
        idx_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Return the nth term of A335237 (indexing starts at 1). */
seq_t a(idx_t n)
{
    if (n == 1)                /* a(1) = 0 */
        return (seq_t)0;

    idx_t count = 1;           /* 0 has already been counted */
    for (idx_t cand = 1; ; ++cand) {
        idx_t temp = cand;
        idx_t pos = 1;          /* bit position, 1-based */
        idx_t positions[64];
        idx_t poscnt = 0;
        int found_common = 0;   /* set when a pair of indices shares gcd > 1 */

        while (temp) {
            if (temp & 1) {
                if (poscnt == 0) {
                    positions[poscnt++] = pos;          /* first index kept */
                } else {
                    /* check new index against previous ones */
                    for (idx_t k = 0; k < poscnt; ++k) {
                        if (gcd_idx(pos, positions[k]) > 1) {
                            found_common = 1;
                            break;
                        }
                    }
                    if (found_common)          /* early exit */
                        break;
                    positions[poscnt++] = pos;          /* store new index */
                }
            }
            temp >>= 1;
            ++pos;
            if (poscnt > 64)        /* safety, should not happen for 64‑bit candidates */
                break;
        }

        if (found_common) {           /* candidate satisfies the property */
            ++count;
            if (count == n)
                return (seq_t)cand;
        }
    }
}
